INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (67, 1, 'ISR 이 무엇인지 알기', 'Kafka 에서 "복제본이 3개 있다(replication factor 3)"와 **ISR(In-Sync Replica)** 은 어떻게 다를까요?', '"몇 개 있는가"와 "그중 몇 개가 지금 믿을 만한가"는 다른 질문입니다.', NULL, NULL, '[]', 'choice', '["ISR 은 replication factor 와 항상 같은 숫자이다", "replication factor 는 복제본 **개수**이고, ISR 은 그중 Leader 를 **충분히 따라잡고 있는** 복제본의 집합이다 (Leader 자신도 포함)", "ISR 은 consumer 가 읽고 있는 파티션의 집합이다", "ISR 은 디스크가 가장 큰 브로커의 목록이다"]', 1, 'Follower 가 `replica.lag.time.max.ms` 안에 Leader 에게 fetch 하지 못하면 ISR 에서 빠지고, 다시 따라잡으면 복귀합니다. 장애를 점검할 때 `--describe` 의 `Isr` 이 `1,2,3` 처럼 전부 들어 있는지 보는 것이 복제 상태 확인의 첫걸음입니다.', NULL, NULL, NULL, NULL),
  (67, 2, 'acks 설정과 전달 보장 알기', '프로듀서가 메시지를 보낼 때 **ISR 에 있는 모든 복제본**이 받은 뒤에야 성공으로 처리하게 하려면 어떤 값을 쓸까요?', '0 은 기다리지 않음, 1 은 Leader 만, 그다음 단계가 있습니다.', NULL, NULL, '[]', 'choice', '["`acks=0`", "`acks=1`", "`acks=none`", "`acks=all` (또는 -1)"]', 3, '`acks=0` 은 응답을 기다리지 않아 가장 빠르지만 유실될 수 있고(at-most-once), `acks=1` 은 Leader 가 받으면 OK 입니다(Leader 가 복제 전에 죽으면 유실 가능). `acks=all` 은 ISR 전체가 받아야 하므로 가장 안전하며, 보통 `min.insync.replicas` 와 함께 설정합니다.', NULL, NULL, NULL, NULL),
  (67, 3, 'min.insync.replicas 의 역할 알기', '`acks=all` 이고 `min.insync.replicas=2` 인 토픽에서 ISR 이 **1개**(Leader 뿐)로 줄었습니다. 프로듀서의 쓰기는 어떻게 될까요?', '"최소 몇 개가 동기화되어 있어야 쓰기를 받아 주는가"를 정하는 값입니다.', NULL, NULL, '[]', 'choice', '["Leader 혼자 받아 정상적으로 성공한다", "메시지가 자동으로 다른 토픽에 저장된다", "쓰기가 **거부**된다 (NotEnoughReplicas). 복제가 부족한 상태에서 받았다가 유실되는 것을 막기 위해서이다", "consumer 만 막히고 쓰기는 그대로 된다"]', 2, '`min.insync.replicas` 는 쓰기가 성공하려면 ISR 에 최소 몇 개가 있어야 하는지입니다. 모자라면 안전을 위해 쓰기를 거부합니다. 가용성과 내구성의 트레이드오프이며 보통 replication factor 3 에 min.insync 2 를 씁니다.', NULL, NULL, NULL, NULL),
  (67, 4, 'Controller 와 파티션 Leader 구분하기', 'Kafka 의 **Controller** 와 **파티션 Leader** 에 대한 설명으로 알맞은 것은 무엇일까요?', '하나는 클러스터 전체에 딱 한 대, 하나는 파티션마다 있습니다.', NULL, NULL, '[]', 'choice', '["Controller 는 클러스터에 한 대뿐이며 \\"어느 브로커가 어느 파티션의 Leader 인가\\"를 정하고 전파한다. 파티션 Leader 는 파티션마다 있고 producer·consumer 가 실제로 데이터를 주고받는 대상이다", "Controller 는 파티션마다 한 대씩 있고 데이터를 저장한다", "둘은 같은 역할의 다른 이름이다", "파티션 Leader 는 클러스터에 한 대뿐이다"]', 0, '같은 브로커가 어떤 파티션에서는 Leader, 어떤 파티션에서는 Follower 일 수 있습니다. Controller 는 데이터를 주고받지 않고 메타데이터(Leader 배정)를 관리합니다. KRaft 모드에서는 컨트롤러 쿼럼이 이 일을 합니다.', NULL, NULL, NULL, NULL),
  (67, 5, 'KRaft 3대를 재시작하는 올바른 방법', 'KRaft 쿼럼으로 구성한 Kafka 브로커 **3대**에 설정을 반영하려고 합니다. 안전한 방법은 무엇일까요?', '쿼럼은 과반이 살아 있어야 유지됩니다.', NULL, NULL, '[]', 'choice', '["3대를 동시에 재시작해 시간을 줄인다", "**1대씩 순차로** 재시작하고, 한 대가 정상으로 복귀(ISR·쿼럼)한 것을 확인한 뒤 다음 대를 한다", "2대를 동시에 재시작한다", "재시작하지 않고 설정 파일만 바꾼다"]', 1, '동시에 재시작하면 쿼럼과 ISR 이 한꺼번에 사라져 서비스가 멈추고 데이터 정합성 문제가 생길 수 있습니다. 사이트별 3대도 순차로, 한 대 재시작 후에는 `--describe` 로 ISR 이 복구됐는지, 컨트롤러 Leader 가 정상인지 확인하고 넘어갑니다.', NULL, NULL, NULL, NULL),
  (67, 6, 'advertised.listeners 가 필요한 이유 알기', 'Kafka 클라이언트가 bootstrap 서버에 접속은 되는데 **그다음 재연결에서 계속 실패**합니다. 가장 먼저 의심할 것은 무엇일까요?', '클라이언트는 처음 접속한 뒤 브로커가 돌려준 주소로 다시 접속합니다.', NULL, NULL, '[]', 'choice', '["`retention.ms` 가 너무 짧은지", "토픽 이름에 특수문자가 있는지", "consumer 의 `group.id` 가 너무 긴지", "브로커의 `advertised.listeners` 주소가 클라이언트가 **실제로 접근할 수 없는 주소**인지"]', 3, 'bootstrap 은 "최초 접속용"일 뿐이고, 이후 메시지는 메타데이터에 담긴 각 브로커의 **advertised 주소**로 직접 연결합니다. 그래서 그 주소가 클라이언트에서 닿지 않으면 첫 접속만 되고 이후가 실패합니다. 네트워크가 분리되었거나 컨테이너 플랫폼 내부의 Kafka 처럼 주소 체계가 다른 환경에서 자주 생깁니다.', NULL, NULL, NULL, NULL),
  (67, 7, 'HAProxy 뒤의 Kafka 는 왜 브로커마다 포트가 다를까', 'Kafka 브로커 3대를 HAProxy 로 노출할 때, 브로커별로 **서로 다른 포트**(예: 19092, 19093, 19094)로 매핑하는 이유는 무엇일까요?', '클라이언트는 브로커 한 대가 아니라 **각 브로커**와 따로 연결해야 합니다.', NULL, NULL, '[]', 'choice', '["클라이언트가 파티션 Leader 인 **특정 브로커에 직접** 연결해야 하므로, 브로커마다 구분되는 외부 주소(포트)를 advertised 로 알려 줘야 한다", "포트가 달라야 HAProxy 가 시작되기 때문이다", "로드밸런싱 알고리즘이 라운드로빈이라서이다", "브로커가 같은 포트를 두 번 열 수 없어서이다"]', 0, '일반 웹 서비스와 달리 Kafka 는 "아무 서버나" 받으면 안 됩니다. 쓰기·읽기는 해당 파티션의 Leader 브로커로 가야 하므로, HAProxy 는 L4 로 포트별 1:1 포워딩을 하고 각 브로커의 advertised 주소를 그 포트로 맞춥니다.', NULL, NULL, NULL, NULL),
  (67, 8, '로그 보관정책 알기', 'Kafka 가 디스크를 계속 차지하지 않도록 오래된 메시지를 자동으로 정리하게 하려면 어떤 개념을 설정할까요?', '토픽의 retention(보관) 정책입니다.', NULL, NULL, '[]', 'choice', '["`acks=all`", "`advertised.listeners`", "`retention.ms`(보관 기간)·`retention.bytes`(크기) 같은 보관 설정과 `cleanup.policy=delete`", "`min.insync.replicas`"]', 2, 'Kafka 는 읽어도 지우지 않고, 보관 기간(또는 크기)이 지난 세그먼트를 삭제합니다. 설정을 바꿀 때는 먼저 현재 값을 점검하고, 백업한 뒤 노드마다 순차로 적용하며, 삭제가 실제로 동작하는지 확인합니다. 로그가 뜸한 appender 는 수동 정리가 필요할 수 있습니다.', NULL, NULL, NULL, NULL),
  (67, 9, 'connect-offsets 토픽의 조건 알기', 'Kafka Connect 가 시작하자마자 종료를 반복하고 `Topic ''connect-offsets'' is required to have cleanup.policy=compact` 라고 나옵니다. 원인은 무엇일까요?', 'offset 은 "키별 최신 값"만 의미 있습니다.', NULL, NULL, '[]', 'choice', '["브로커의 CPU 가 부족해서이다", "내부 토픽(`connect-offsets` 등)을 재생성할 때 `cleanup.policy=compact` 없이 만들어졌기 때문이다. 설정 변경이 안 먹으면 **삭제 후 올바른 설정으로 재생성**한다", "Debezium 플러그인이 설치되지 않아서이다", "consumer lag 가 너무 커서이다"]', 1, '`connect-offsets`, `connect-config`, `connect-status` 는 키별 최신 상태가 중요해서 **compact** 가 필수입니다. delete 정책이면 오래된 offset 이 지워져 위치를 잃을 수 있습니다. 이 토픽을 지우고 재생성하기 전에는 Connect 를 모든 서버에서 중지해야 합니다.', NULL, NULL, NULL, NULL),
  (67, 10, '전달 보장 단계 알기', '네트워크 오류로 응답이 유실되어 프로듀서가 같은 메시지를 **재전송**했습니다. 브로커에 중복이 쌓이지 않으려면 무엇이 필요할까요?', '프로듀서가 보낸 ID 와 순번으로 중복을 걸러냅니다.', NULL, NULL, '[]', 'choice', '["멱등 프로듀서(`enable.idempotence=true`). 소비 쪽에서도 같은 메시지가 다시 와도 한 번만 반영되게(멱등) 처리해야 exactly-once 에 가까워진다", "`retention.ms` 를 0 으로 한다", "consumer 를 하나만 둔다", "토픽 파티션을 1개로 줄인다"]', 0, '"응답 유실 → 재전송"은 막을 수 없어서 at-least-once 에서는 중복이 생깁니다. 그래서 exactly-once 는 재전송 자체를 막는 것이 아니라 **재전송이 와도 한 번만 처리되게** 만드는 일이고, 프로듀서 쪽(멱등)과 소비·적재 쪽(upsert, 중복 제거) 양쪽에서 해야 합니다.', NULL, NULL, NULL, NULL);
